/* Lanka Global Access — university profile page behaviour
 * (pages generated by scripts/generate-university-pages.js)
 *  - "Read more" for long About sections
 *  - search + study-level filter for the course list
 */
(function () {
    'use strict';

    function aboutToggle() {
        const wrap = document.querySelector('.up-about');
        const btn = document.getElementById('up-about-toggle');
        if (!wrap || !btn) return;
        if (wrap.scrollHeight <= 380) { wrap.dataset.collapsed = 'false'; return; }
        btn.classList.remove('hidden');
        btn.addEventListener('click', () => {
            const collapsed = wrap.dataset.collapsed === 'true';
            wrap.dataset.collapsed = String(!collapsed);
            btn.textContent = collapsed ? 'Show less' : 'Read more';
            if (!collapsed) wrap.scrollIntoView({ block: 'nearest' });
        });
    }

    function courseFilter() {
        const list = document.getElementById('up-course-list');
        if (!list) return;
        const input = document.getElementById('up-course-search');
        const empty = document.getElementById('up-course-empty');
        const items = [...list.querySelectorAll('.up-course')];
        const buttons = [...document.querySelectorAll('[data-up-level]')];
        let level = '';

        function apply() {
            const terms = (input?.value || '').toLowerCase().split(/\s+/).filter(Boolean);
            let shown = 0;
            items.forEach(item => {
                const ok = (!level || item.dataset.level === level) && terms.every(t => item.dataset.search.includes(t));
                item.hidden = !ok;
                if (ok) shown += 1;
            });
            if (empty) empty.classList.toggle('hidden', shown > 0);
        }
        input?.addEventListener('input', apply);
        buttons.forEach(btn => btn.addEventListener('click', () => {
            level = btn.dataset.upLevel;
            buttons.forEach(b => b.setAttribute('aria-pressed', String(b === btn)));
            apply();
        }));
    }

    function init() { aboutToggle(); courseFilter(); }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
})();
